import React, { useState } from "react";
import "./clippreview.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faScissors, faPlay, faPause, faDownload } from "@fortawesome/free-solid-svg-icons";

function ClipPreview({ videoUrl, videoThumbnail }) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [clipStart, setClipStart] = useState(0);
  const [clipEnd, setClipEnd] = useState(0);
  const [loading, setLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState("");

  // Toggle play/pause logic
  const handlePlayPause = () => {
    setIsPlaying((prev) => !prev);
  };

  // Call backend to process video
  const handleClip = async () => {
    if (clipStart < 0 || clipEnd <= clipStart) {
      alert("Please enter a valid clip range (end > start).");
      return;
    }

    setLoading(true);
    setResponseMessage("");

    try {
      const response = await fetch("/api/process_short_form_video/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ url: videoUrl }),
      });

      const result = await response.json();

      if (response.ok) {
        setResponseMessage(result.output); // Assuming 'output' is the successful response from the backend
      } else {
        setResponseMessage(result.error); // Handle error response
      }
    } catch (error) {
      console.error("Error processing video:", error);
      setResponseMessage("An error occurred while processing the video.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="clipping-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content */}
      <main className="main-content">
        {/* Clipper Section */}
        <section className="clipper-section">
          <button className="clipper-btn" onClick={handleClip} disabled={loading}>
            {loading ? "Processing..." : "Create Clip"}
          </button>

          {/* Long Video Section */}
          <div className="long-video">
            <h2>Your long video</h2>
            <div className="video-preview">
              {videoUrl ? (
                <video src={videoUrl} controls className="preview-video" />
              ) : (
                <img
                  src={videoThumbnail || "https://via.placeholder.com/300x200"}
                  alt="Video Thumbnail"
                  className="preview-image"
                />
              )}
            </div>
          </div>

          {/* Show Response Message */}
          {responseMessage && <div className="response-message">{responseMessage}</div>}
        </section>
      </main>
    </div>
  );
}

export default ClipPreview;
